import{_ as t,o as i,c as a,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.4.19 Add Workspace Member","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-19-add-workspace-member/spec.md","filePath":"feature/agency-workspace/3-4-19-add-workspace-member/spec.md"}'),n={name:"feature/agency-workspace/3-4-19-add-workspace-member/spec.md"};function s(r,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-4-19-add-workspace-member" tabindex="-1">3.4.19 Add Workspace Member <a class="header-anchor" href="#_3-4-19-add-workspace-member" aria-label="Permalink to &quot;3.4.19 Add Workspace Member&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.19</td></tr><tr><td>Feature</td><td>Add Workspace Member</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER (of the Workspace)</td></tr><tr><td>Version</td><td>2.3 — 2026-09-23 — rewritten to the standard FR format</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when the MANAGER of a Workspace adds a member, either by inviting an email address or by assigning a user who already belongs to the Agency.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose:</strong> Brings people into the Workspace with the right role, either by inviting them by email or by directly assigning people who are already in the Agency.</li><li><strong>Interface:</strong> &quot;Add Member&quot; action on the members screen, offering two distinct paths — &quot;Invite by email&quot; and &quot;Assign from Agency&quot;, the latter selecting from existing Agency members.</li><li><strong>Data Processing:</strong> For an invitation the system records a pending invitation and sends an email; for an assignment the system creates active memberships immediately and reports which users were added and which were skipped because they were already active members.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Add Workspace Member Screen:</p><ul><li>An &quot;Add Member&quot; action on <code>/workspaces/:id/members</code>.</li><li>An &quot;Invite by email&quot; tab with email, role, and an optional note.</li><li>An &quot;Assign from Agency&quot; tab listing existing Agency members with a role choice per person.</li><li>After an assignment, the result shows the members added and a notice for the users skipped because they were already members.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the caller&#39;s authenticated identity. For an invitation: email and role. For an assignment: at least one entry of <code>{userId, role}</code>.</li><li><strong>Input optional:</strong> note (invitation only).</li><li><strong>System data:</strong> The caller&#39;s role in the Workspace; the count of active MANAGERs in the Workspace; whether the email already has an active membership or a pending invitation; the Agency membership of each assigned user.</li><li><strong>Output:</strong> For an invitation, an acknowledgement with no content returned. For an assignment, the members added — id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive — together with <code>skippedUserIds</code>, the identifiers skipped because those users were already active members. <code>role</code> is one of MANAGER, CREATOR, CLIENT.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-27:</strong> Invite path — only OWNER/MANAGER may invite; an already-active member cannot be re-invited (→ 409 <code>ALREADY_IN_WORKSPACE</code>, guard checked first); a second invite is blocked while a pending unexpired invitation exists for the same email (→ 409 <code>INVITATION_ALREADY_PENDING</code>, guard checked second); the invitation token is a random UUID with an expiry window.</li><li><strong>BR-35:</strong> <code>@RequireRoleAspect</code> re-reads the caller&#39;s role from the DB at request time; <code>SystemRole.ADMIN</code> bypasses the check. The role check (MANAGER required) runs before any service-level guard.</li><li><strong>BR-02:</strong> The invitation path does not create a membership immediately — it records a pending invitation that the invitee must accept before becoming a member.</li><li><strong>BR-05 (duplicate-MANAGER guard, checked third):</strong> Requesting the MANAGER role while the Workspace already has an active MANAGER → 409 <code>MANAGER_ALREADY_ASSIGNED</code>, on both the invitation and the assignment path; a Workspace has exactly one active MANAGER at any time.</li><li><strong>BR-06:</strong> The assignment path creates active memberships immediately and needs no acceptance step.</li><li><strong>BR-07:</strong> An assignment entry whose user already has an active membership in the Workspace is skipped without error and its identifier is reported in <code>skippedUserIds</code>; the remaining entries in the batch are still processed.</li><li><strong>BR-08:</strong> An assignment entry whose user is not a member of the Agency → 403 <code>NOT_AGENCY_MEMBER</code>.</li><li><strong>BR-09:</strong> An assignment entry whose user record does not exist → <code>USER_NOT_FOUND</code>.</li><li><strong>BR-31:</strong> Code <code>MemberRole</code> enum has three workspace roles — MANAGER, CREATOR, CLIENT; there is no Workspace-level OWNER (OWNER exists only at Agency level, <code>AgencyMemberRole</code>). ⚠ BA conflict (needs team decision): <code>Section5_Requirement_Appendix.md</code> BR-31 still lists &quot;OWNER, MANAGER, CREATOR, CLIENT&quot; as the four workspace roles — that wording is stale against the current code, which moved OWNER to the Agency level and left <code>MemberRole</code> with only MANAGER/CREATOR/CLIENT (see <code>MemberRole.java</code> comment: &quot;OWNER đã chuyển lên cấp Agency&quot;). Invited or assigned roles must be one of MANAGER, CREATOR, CLIENT.</li><li><strong>BR-32:</strong> Role assignment happens at invite time; the role is stored on the invitation and carried to the member row on acceptance.</li><li><strong>BR-11:</strong> Roles are independent per Workspace — the same user may hold a different role in another Workspace of the same Agency.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller must be the MANAGER of that Workspace; otherwise 403 <code>FORBIDDEN</code> (BR-35). Display: MSG39.</li><li>email empty → Display: MSG02.</li><li>role empty → Display: MSG02.</li><li>Invitation: <code>email</code> must be a well-formed email address; otherwise Display: MSG04.</li><li>Invitation: <code>role</code> must be one of MANAGER, CREATOR, CLIENT (BR-31, BR-82); otherwise Display: MSG95.</li><li>Assignment: the member list must contain at least one entry; otherwise 400 <code>VALIDATION_ERROR</code>.</li><li>Assignment: every <code>userId</code> must belong to an Agency member; otherwise 403 <code>NOT_AGENCY_MEMBER</code>.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>MANAGER opens the members screen and chooses &quot;Add Member&quot;.</li><li>On the invite path, the MANAGER enters an email, a role, and an optional note; on the assign path, the MANAGER picks one or more existing Agency members and a role for each.</li><li>System confirms the caller holds the MANAGER role in the Workspace (BR-35); otherwise the request fails with 403 <code>FORBIDDEN</code>.</li><li>Invite path: system normalises the email, checks for an existing active membership and for a pending invitation, and applies the single-MANAGER rule when the role is MANAGER (BR-27, BR-05).</li><li>Invite path: system records a pending invitation with an expiry and sends the invitation email (BR-27, BR-02); toast MSG33.</li><li>Assign path: system validates each entry against Agency membership, skips users who are already active members, applies the single-MANAGER rule, and creates active memberships immediately.</li><li>Assign path: system returns the members added together with the identifiers of the users skipped.</li><li>Screen refreshes the member list with the members added and can show a notice for the skipped users.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Caller is not the MANAGER of the Workspace (BR-35) → 403 <code>FORBIDDEN</code>, toast MSG39. 3.a2: The screen blocks the action; the caller cannot add members without the MANAGER role.</li><li>4.a1: Invitation for an email that already has an active membership (BR-27) → 409 <code>ALREADY_IN_WORKSPACE</code>, toast MSG34. 4.a2: The MANAGER checks the existing member list instead of re-inviting.</li><li>4.b1: Invitation for an email that already has a pending, unexpired invitation (BR-27) → 409 <code>INVITATION_ALREADY_PENDING</code>, toast MSG35. 4.b2: The MANAGER waits for the pending invitation to be accepted or to expire before retrying.</li><li>4.c1: MANAGER role requested while the Workspace already has an active MANAGER (BR-05) → 409 <code>MANAGER_ALREADY_ASSIGNED</code>, Display: MSG95 (generic role-rejection message; no dedicated MSG code exists for this conflict — see report). 4.c2: The MANAGER picks CREATOR or CLIENT instead, or hands over the MANAGER role first.</li><li>Assignment entry whose user is outside the Agency → 403 <code>NOT_AGENCY_MEMBER</code>.</li><li>Assignment entry whose user does not exist → <code>USER_NOT_FOUND</code>.</li><li>Assignment where some users are already active members → those identifiers appear in <code>skippedUserIds</code>, no entry for them appears in the added list, no error is raised, and the rest of the batch is processed.</li><li>Invitation, email missing → Display: MSG02. Role missing → Display: MSG02. Email malformed → Display: MSG04.</li><li>Assignment with an empty member list → 400 <code>VALIDATION_ERROR</code>.</li><li>Invitation of a person who has an account in the system but has never joined this Agency → the invitation is still sent, because the invite path does not require Agency membership.</li><li>Assignment of a user who holds a different role in another Workspace of the same Agency → valid, since roles are independent per Workspace.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>Invite path: a pending invitation exists for the email with an expiry date, and the invitation email has been dispatched.</li><li>Assign path: active membership rows exist for every valid entry, and the identifiers of the skipped users have been reported.</li><li>The Workspace still has exactly one active MANAGER.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>None.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
